def norm(res):
 d=(res or {}).get('data') or {}
 recs=d.get('records') or d.get('rows') or []
 out=[]
 for r in recs:
  if isinstance(r,dict) and isinstance(r.get('fields'),dict):
   row=dict(r['fields']); row.setdefault('id',r.get('id')); out.append(row)
  else: out.append(r)
 return out
